parameters.jsCode:
// Data reduction - VirusTotal (PRIMARY source)
// Turns the raw VirusTotal v3 IP report into a compact evidence object and
// starts the `record` that every following node reads and extends.
// Mode: Run Once for Each Item.

const observable = $('Select pending observable').item.json;
const res = $json; // full HTTP response: { statusCode, body }

let status;
if (res.statusCode === 200) {
  status = 'ok';
} else if (res.statusCode === 404) {
  status = 'no_data'; // VirusTotal has never seen this IP
} else {
  // Quota (429), auth (401/403) and server errors must never be stored as a
  // clean verdict. Failing here leaves the observable in the queue, so the
  // next scheduled run retries it.
  const msg = res.body?.error?.message || res.statusMessage || 'unknown error';
  throw new Error(`VirusTotal HTTP ${res.statusCode} for ${observable.observable_ip}: ${msg}`);
}

const body = res.body && typeof res.body === 'object' ? res.body : {};
const attr = body.data?.attributes || {};
const stats = attr.last_analysis_stats || {};
const num = (v) => (Number.isFinite(Number(v)) ? Number(v) : 0);

// Engines that flagged the IP; malicious first, then suspicious.
const flaggedBy = Object.entries(attr.last_analysis_results || {})
  .filter(([, r]) => r && (r.category === 'malicious' || r.category === 'suspicious'))
  .map(([engine, r]) => ({ engine, category: r.category, result: r.result || null }))
  .sort((a, b) => (a.category === b.category ? a.engine.localeCompare(b.engine) : a.category === 'malicious' ? -1 : 1));

const vt = {
  status,
  malicious: num(stats.malicious),
  suspicious: num(stats.suspicious),
  harmless: num(stats.harmless),
  undetected: num(stats.undetected),
  engines_total: Object.values(stats).reduce((sum, v) => sum + num(v), 0),
  flagged_by: flaggedBy.slice(0, 25), // bounded for the prompt
  as_owner: attr.as_owner || null,
  asn: attr.asn || null,
  country: attr.country || null,
  network: attr.network || null,
  reputation: attr.reputation ?? null,
  tags: Array.isArray(attr.tags) ? attr.tags : [],
  last_analysis_date: attr.last_analysis_date ? new Date(attr.last_analysis_date * 1000).toISOString() : null,
};

const gateMin = Number($('Load AI configuration').first().json.settings.vt_gate_min_malicious);

return {
  json: {
    record: {
      observable: {
        dns_query_id: Number(observable.dns_query_id),
        fqdn: observable.fqdn,
        observable_ip: observable.observable_ip,
        source_ips: observable.source_ips,
        query_count: Number(observable.query_count), // BIGINT arrives as a string
        first_seen: observable.first_seen,
        last_seen: observable.last_seen,
      },
      vt,
      gate: { min_malicious: gateMin, passed: status === 'ok' && vt.malicious >= gateMin },
      // Raw payloads are written to cyber_sentinel.threat_data_raw by "Insert raw payloads".
      raw: status === 'ok'
        ? [{ source: 'VirusTotal', resource: observable.observable_ip, payload: body }]
        : [],
    },
  },
};

// Data reduction - abuse.ch (SUPPORTING sources: ThreatFox + URLhaus)
// Adds compact ThreatFox and URLhaus evidence to the record and builds the
// `features` object consumed by cyber_sentinel_ai.compute_threat_score().
// A failed lookup never stops the pipeline: it is recorded as status "error"
// and the scoring trace shows it.
// Mode: Run Once for Each Item.

const record = $('Data reduction - VirusTotal').item.json.record;
const settings = $('Load AI configuration').first().json.settings;
const tfRes = $('Abuse.CH_ThreatFox request').item.json;
const uhRes = $json; // Abuse.CH_URLHaus request
const obs = record.observable;

// Normalises an HTTP node result (full response, or the error output).
function httpOutcome(res) {
  if (!res || res.error) return { ok: false, error: String(res?.error?.message || res?.error || 'request failed') };
  if (res.statusCode !== 200) return { ok: false, error: `HTTP ${res.statusCode}` };
  let body = res.body;
  if (typeof body === 'string') {
    try { body = JSON.parse(body); } catch (e) { return { ok: false, error: 'non-JSON response' }; }
  }
  return body && typeof body === 'object' ? { ok: true, body } : { ok: false, error: 'empty response' };
}

// Host part of any ThreatFox IOC type: "ip:port", domain or URL.
function iocHost(ioc) {
  try {
    return new URL(String(ioc).includes('://') ? ioc : `http://${ioc}`).hostname.toLowerCase();
  } catch (e) {
    return null;
  }
}

// abuse.ch timestamps look like "2026-09-01 10:11:12 UTC".
function parseAbuseDate(value) {
  if (typeof value !== 'string' || !value) return null;
  const d = new Date(value.replace(' UTC', 'Z').replace(' ', 'T'));
  return Number.isNaN(d.getTime()) ? null : d;
}

// URLs are untrusted data: defang them for the prompt and the e-mail.
const defang = (url) => String(url).replace(/^http/i, 'hxxp').replace(/\./g, '[.]');

function countTop(values, limit) {
  const counts = {};
  for (const v of values) {
    const key = String(v || '').trim().toLowerCase();
    if (key) counts[key] = (counts[key] || 0) + 1;
  }
  return Object.entries(counts)
    .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))
    .slice(0, limit)
    .map(([value, count]) => ({ value, count }));
}

// ---------- ThreatFox (searched by IP) ----------
const tfHttp = httpOutcome(tfRes);
let threatfox;
if (!tfHttp.ok) {
  threatfox = { status: 'error', error: tfHttp.error };
} else if (tfHttp.body.query_status === 'no_result') {
  threatfox = { status: 'no_data' };
} else if (tfHttp.body.query_status !== 'ok') {
  threatfox = { status: 'error', error: `query_status=${tfHttp.body.query_status}` };
} else {
  // The search matches substrings (1.2.3.4 also finds 1.2.3.45:80), and an exact
  // search would miss "ip:port" C2 entries - so keep IOCs whose host is the IP.
  const iocs = (Array.isArray(tfHttp.body.data) ? tfHttp.body.data : [])
    .filter((d) => iocHost(d.ioc) === String(obs.observable_ip).toLowerCase());
  if (iocs.length === 0) {
    threatfox = { status: 'no_data' };
  } else {
    const cutoff = Date.now() - Number(settings.tf_active_days) * 86400000;
    const seen = iocs.map((d) => parseAbuseDate(d.last_seen) || parseAbuseDate(d.first_seen)).filter(Boolean);
    threatfox = {
      status: 'ok',
      ioc_count: iocs.length,
      active: seen.some((d) => d.getTime() >= cutoff),
      // "Unknown malware" is a ThreatFox placeholder, not an identified family.
      malware_families: [...new Set(iocs.map((d) => d.malware_printable).filter((m) => m && !/^unknown/i.test(m)))],
      threat_types: [...new Set(iocs.map((d) => d.threat_type).filter(Boolean))],
      max_confidence: Math.max(...iocs.map((d) => Number(d.confidence_level) || 0)),
      last_seen: seen.length ? new Date(Math.max(...seen)).toISOString() : null,
      tags: countTop(iocs.flatMap((d) => d.tags || []), 10),
      iocs: iocs.slice(0, 10).map((d) => ({
        ioc: defang(d.ioc),
        threat_type: d.threat_type || null,
        malware: d.malware_printable || null,
        confidence: Number(d.confidence_level) || 0,
        first_seen: d.first_seen || null,
        last_seen: d.last_seen || null,
      })),
    };
  }
}

// ---------- URLhaus (searched by domain - URLs are hosted on names) ----------
const uhHttp = httpOutcome(uhRes);
let urlhaus;
if (!uhHttp.ok) {
  urlhaus = { status: 'error', error: uhHttp.error };
} else if (uhHttp.body.query_status === 'no_results') {
  urlhaus = { status: 'no_data' };
} else if (uhHttp.body.query_status !== 'ok') {
  urlhaus = { status: 'error', error: `query_status=${uhHttp.body.query_status}` };
} else {
  const urls = Array.isArray(uhHttp.body.urls) ? uhHttp.body.urls : [];
  const online = urls.filter((u) => u.url_status === 'online');
  urlhaus = {
    status: 'ok',
    url_count: Number(uhHttp.body.url_count) || urls.length,
    urls_online: online.length,
    threats: countTop(urls.map((u) => u.threat), 5),
    tags: countTop(urls.flatMap((u) => u.tags || []), 10),
    blacklists: uhHttp.body.blacklists || null,
    online_samples: online.slice(0, 5).map((u) => ({ url: defang(u.url), threat: u.threat || null })),
    reference: uhHttp.body.urlhaus_reference || null,
  };
}

return {
  json: {
    record: {
      ...record,
      threatfox,
      urlhaus,
      features: {
        fqdn: obs.fqdn,
        vt_status: record.vt.status,
        vt_malicious: record.vt.malicious,
        vt_as_owner: record.vt.as_owner,
        tf_status: threatfox.status,
        tf_ioc_count: threatfox.ioc_count || 0,
        tf_active: threatfox.active === true,
        tf_malware_families: threatfox.malware_families || [],
        uh_status: urlhaus.status,
        uh_urls_online: urlhaus.urls_online || 0,
      },
      raw: [
        ...record.raw,
        { source: 'Abuse_ThreatFox', resource: obs.observable_ip, payload: tfHttp.ok ? tfHttp.body : null },
        { source: 'Abuse_URLhaus', resource: obs.fqdn, payload: uhHttp.ok ? uhHttp.body : null },
      ],
    },
  },
};

// Supporting sources not checked
// VirusTotal detections are below the gate, so ThreatFox and URLhaus are not
// queried. The record gets the same `features` shape as the enriched path,
// so "Compute rule-based score" works identically for both branches.
// Mode: Run Once for Each Item.

const record = $json.record;

return {
  json: {
    record: {
      ...record,
      threatfox: { status: 'not_checked' },
      urlhaus: { status: 'not_checked' },
      features: {
        fqdn: record.observable.fqdn,
        vt_status: record.vt.status,
        vt_malicious: record.vt.malicious,
        vt_as_owner: record.vt.as_owner,
        tf_status: 'not_checked',
        uh_status: 'not_checked',
      },
    },
  },
};

parameters.query:
-- Deterministic scoring rules (steps 1-5); thresholds live in cyber_sentinel_ai.ai_settings.
SELECT $1::jsonb || jsonb_build_object(
           'rule', cyber_sentinel_ai.compute_threat_score($1::jsonb -> 'features')
       ) AS record;

parameters.jsCode:
// Build AI prompt
// Prepares both messages for the AI Agent. Everything comes from the database
// or from this run's evidence - nothing is hard-coded in the workflow:
//   system message -> active row of cyber_sentinel_ai.prompt_templates
//   threat scale   -> cyber_sentinel.v_threat_scale_for_agent
//   rule_engine    -> cyber_sentinel_ai.compute_threat_score()
//   evidence       -> VirusTotal / ThreatFox / URLhaus (raw payloads excluded)
// Mode: Run Once for Each Item.

const config = $('Load AI configuration').first().json;
const record = $('Compute rule-based score').item.json.record;

if (!config.system_prompt) {
  throw new Error('No active prompt: set is_active = true on one row of cyber_sentinel_ai.prompt_templates');
}

const systemMessage = config.system_prompt
  .replaceAll('[[THREAT_SCALE]]', config.threat_scale)
  .replaceAll('[[MAX_DEVIATION]]', String(config.settings.ai_max_deviation));

// Refuse to send a prompt with an unresolved placeholder.
const leftover = systemMessage.match(/\[\[[A-Z_]+\]\]/);
if (leftover) {
  throw new Error(`Unresolved placeholder ${leftover[0]} in prompt version ${config.prompt_version}`);
}

const userMessage = {
  observable: {
    domain: record.observable.fqdn,
    ip: record.observable.observable_ip,
    dns_query_count: record.observable.query_count,
    first_seen: record.observable.first_seen,
    last_seen: record.observable.last_seen,
  },
  evidence: {
    virustotal: record.vt,
    threatfox: record.threatfox,
    urlhaus: record.urlhaus,
  },
  rule_engine: record.rule,
};

return {
  json: {
    system_message: systemMessage,
    user_message: JSON.stringify(userMessage, null, 2),
    record,
  },
};

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "verdict_label": {
      "type": "string",
      "description": "2-5 word English label"
    },
    "summary_en": {
      "type": "string",
      "description": "One or two English sentences"
    },
    "primary_evidence": {
      "type": "string",
      "description": "VirusTotal (and ThreatFox) facts with numbers"
    },
    "supporting_context": {
      "type": "string",
      "description": "What URLhaus and historical verdicts added, or 'none'"
    },
    "analysis_pl": {
      "type": "string",
      "description": "2-4 sentences in Polish for the analyst"
    },
    "proposed_score": {
      "type": "integer",
      "minimum": 1,
      "maximum": 5
    },
    "deviation_reason": {
      "type": "string",
      "description": "Empty when proposed_score equals rule_score"
    },
    "historical_match_ids": {
      "type": "array",
      "items": {
        "type": "integer"
      }
    }
  },
  "required": [
    "verdict_label",
    "summary_en",
    "primary_evidence",
    "supporting_context",
    "analysis_pl",
    "proposed_score",
    "deviation_reason",
    "historical_match_ids"
  ]
}

parameters.jsCode:
// Parse AI Agent output
// Validates the structured answer of the AI Agent and turns it into the
// verdict that is persisted. Safety rules applied here:
//   - the final score may differ from the rule score by at most
//     ai_max_deviation (ai_settings), whatever the model proposes;
//   - if the agent failed or returned something invalid, the rule-based
//     verdict is stored and ai_status = 'failed' (nothing is lost).
// Mode: Run Once for Each Item.

// Keep in sync with the model selected in the "Google Gemini Chat Model" node.
const AI_MODEL = 'gemini-3.1-flash-lite';

const config = $('Load AI configuration').first().json;
const record = $('Build AI prompt').item.json.record;
const agent = $json; // { output: {...} } or { error: ... } (node continues on error)

const ruleScore = Number(record.rule.rule_score);
const maxDeviation = Number(config.settings.ai_max_deviation);
const levels = config.threat_levels;

// Single-line, trimmed text with a length limit.
function text(value, field, { required = true, max = 2000 } = {}) {
  if (typeof value !== 'string') throw new Error(`"${field}" is not a string`);
  const clean = value.replace(/\s+/g, ' ').trim();
  if (required && !clean) throw new Error(`"${field}" is empty`);
  return clean.slice(0, max);
}

let ai = null;
let aiError = null;
try {
  if (agent.error) throw new Error(`AI Agent failed: ${agent.error.message || JSON.stringify(agent.error)}`);
  const out = typeof agent.output === 'string' ? JSON.parse(agent.output) : agent.output;
  if (!out || typeof out !== 'object') throw new Error('AI Agent returned no structured output');

  const proposed = Number(out.proposed_score);
  if (!Number.isInteger(proposed) || proposed < 1 || proposed > 5) {
    throw new Error(`proposed_score must be an integer 1-5, got ${JSON.stringify(out.proposed_score)}`);
  }

  ai = {
    verdict_label: text(out.verdict_label, 'verdict_label', { max: 50 }),
    summary_en: text(out.summary_en, 'summary_en'),
    primary_evidence: text(out.primary_evidence, 'primary_evidence'),
    supporting_context: text(out.supporting_context ?? '', 'supporting_context', { required: false }),
    analysis_pl: text(out.analysis_pl, 'analysis_pl'),
    proposed_score: proposed,
    deviation_reason: text(out.deviation_reason ?? '', 'deviation_reason', { required: false, max: 500 }),
    // Existence of cited ids is checked again in "Insert AI audit".
    historical_match_ids: (Array.isArray(out.historical_match_ids) ? out.historical_match_ids : [])
      .map(Number)
      .filter(Number.isInteger),
  };
} catch (e) {
  aiError = e.message;
}

// Clamp the AI proposal to the allowed window around the rule score.
const finalScore = ai
  ? Math.min(5, Math.max(1, Math.min(ruleScore + maxDeviation, Math.max(ruleScore - maxDeviation, ai.proposed_score))))
  : ruleScore;
const deviated = finalScore !== ruleScore;

const verdict = ai
  ? {
      threat_score: finalScore,
      threat_label: ai.verdict_label,
      summary_en: ai.summary_en,
      analysis_pl: ai.analysis_pl,
    }
  : {
      threat_score: ruleScore,
      threat_label: levels[ruleScore].description.slice(0, 50),
      summary_en: `Rule-based verdict (AI unavailable): ${record.rule.trace.join('; ')}`,
      analysis_pl: null,
    };

// Text stored in vector memory: what the feeds saw plus the verdict.
// Domain and IP are kept in metadata, not in the text, so similarity is
// about threat characteristics rather than identity.
const list = (a, fallback = 'none') => (a && a.length ? a.join(', ') : fallback);
const engineVerdicts = [...new Set(record.vt.flagged_by.map((f) => f.result).filter(Boolean))];
const vectorDocument = ai
  ? [
      `Verdict: ${ai.verdict_label} (score ${finalScore}/5). ${ai.summary_en}`,
      `VirusTotal: ${record.vt.malicious} malicious of ${record.vt.engines_total} engines; verdicts: ${list(engineVerdicts)}.`,
      `Hosting: ${record.vt.as_owner || 'unknown owner'}, country ${record.vt.country || 'unknown'}.`,
      record.threatfox.status === 'ok'
        ? `ThreatFox: malware ${list(record.threatfox.malware_families, 'unidentified')}, threat types ${list(record.threatfox.threat_types)}, ${record.threatfox.active ? 'active' : 'inactive'}.`
        : 'ThreatFox: not listed.',
      record.urlhaus.status === 'ok'
        ? `URLhaus: ${record.urlhaus.url_count} URL(s), ${record.urlhaus.urls_online} online, threats ${list(record.urlhaus.threats.map((t) => t.value))}.`
        : 'URLhaus: not listed.',
    ].join('\n')
  : null;

return {
  json: {
    record: {
      ...record,
      verdict,
      audit: {
        vt_malicious: record.vt.malicious,
        rule_score: ruleScore,
        final_score: finalScore,
        ai_status: ai ? 'ok' : 'failed',
        deviation_reason: deviated ? ai.deviation_reason || 'not given' : null,
        primary_evidence: ai ? ai.primary_evidence : null,
        supporting_context: ai ? ai.supporting_context : null,
        historical_match_ids: ai ? ai.historical_match_ids : [],
        rule_trace: record.rule,
        evidence: { virustotal: record.vt, threatfox: record.threatfox, urlhaus: record.urlhaus },
        ai_error: aiError,
        ai_model: AI_MODEL,
        prompt_version: config.prompt_version,
      },
      vector: vectorDocument ? { document: vectorDocument } : null,
    },
  },
};

// Build clean scan verdict
// Observable below the VirusTotal gate: the rule-based score is the verdict.
// No AI call, no vector memory, no e-mail. It is still persisted, so the
// same domain + IP pair is not looked up again within cache_ttl_days.
// Mode: Run Once for Each Item.

const config = $('Load AI configuration').first().json;
const record = $json.record; // from "Compute rule-based score"
const score = Number(record.rule.rule_score);

return {
  json: {
    record: {
      ...record,
      verdict: {
        threat_score: score,
        threat_label: config.threat_levels[score].description.slice(0, 50),
        summary_en: `Rule-based verdict (below VirusTotal gate, AI not called): ${record.rule.trace.join('; ')}`,
        analysis_pl: null,
      },
      audit: {
        vt_malicious: record.vt.malicious,
        rule_score: score,
        final_score: score,
        ai_status: 'skipped',
        deviation_reason: null,
        primary_evidence: null,
        supporting_context: null,
        historical_match_ids: [],
        rule_trace: record.rule,
        evidence: { virustotal: record.vt, threatfox: record.threatfox, urlhaus: record.urlhaus },
        ai_error: null,
        ai_model: null,
        prompt_version: null,
      },
      vector: null,
    },
  },
};

// Build alert e-mail
// Renders the persisted verdict as a severity-coloured HTML e-mail (same
// look as the original Cyber Sentinel report). Every dynamic value is
// HTML-escaped: domains, URLs and AI text are untrusted input.
// Mode: Run Once for Each Item.

const record = $('Insert AI audit').item.json.record;
const level = $('Load AI configuration').first().json.threat_levels[record.verdict.threat_score];

const esc = (value) => String(value ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;').replace(/'/g, '&#39;');

const score = Number(record.verdict.threat_score);
const theme = score >= 4
  ? { label: '🚨 ALERT', accent: '#f44336', text: '#ff5252', header: '#3a1f1f' }
  : score === 3
    ? { label: '⚠️ REVIEW', accent: '#ffb300', text: '#ffd54f', header: '#332a13' }
    : { label: '✅ INFO', accent: '#4caf50', text: '#81c784', header: '#1b3320' };

const audit = record.audit;
const scoreNote = audit.deviation_reason
  ? `Rule engine ${esc(audit.rule_score)}/5 &rarr; AI adjusted: ${esc(audit.deviation_reason)}`
  : `Rule engine score ${esc(audit.rule_score)}/5 confirmed`;

const section = (title, body) => (body
  ? `<p style="margin:14px 0 4px;color:#888;font-size:12px;text-transform:uppercase;">${title}</p>
     <div style="background:#252525;padding:12px;border-radius:4px;font-size:14px;line-height:1.6;">${esc(body)}</div>`
  : '');

const sources = ['VirusTotal', record.threatfox.status === 'ok' && 'ThreatFox', record.urlhaus.status === 'ok' && 'URLhaus']
  .filter(Boolean)
  .map((s) => `<span style="display:inline-block;background:#37474f;color:#cfd8dc;padding:2px 8px;border-radius:3px;font-size:11px;margin-right:5px;">${s}</span>`)
  .join('');

const html = `<!DOCTYPE html>
<html><body style="font-family:'Segoe UI',Tahoma,sans-serif;background:#121212;color:#e0e0e0;margin:0;padding:20px;">
<div style="max-width:640px;margin:auto;background:#1e1e1e;border:1px solid #333;border-top:4px solid ${theme.accent};border-radius:8px;overflow:hidden;">
  <div style="background:${theme.header};padding:15px;text-align:center;">
    <h2 style="margin:0;color:${theme.text};">${theme.label}: Cyber Sentinel</h2>
  </div>
  <div style="padding:24px;">
    <div style="background:#2d2d2d;border:1px solid #444;border-radius:5px;padding:10px;text-align:center;margin-bottom:18px;">
      <div style="font-size:12px;color:#888;text-transform:uppercase;letter-spacing:1px;">Threat Severity Score</div>
      <div style="font-size:36px;font-weight:bold;color:${theme.text};">${esc(score)}/5</div>
      <div style="font-size:12px;color:#aaa;text-transform:uppercase;">${esc(level.description)} &middot; ${esc(level.action)}</div>
      <div style="font-size:11px;color:#999;margin-top:6px;">${scoreNote}</div>
    </div>
    <p><strong>Obiekt (IP):</strong> <span style="font-family:'Courier New',monospace;color:#64ffda;font-size:18px;font-weight:bold;">${esc(record.observable.observable_ip)}</span></p>
    <p><strong>Powiązana domena:</strong> <span style="color:#90caf9;">${esc(record.observable.fqdn)}</span></p>
    <p><strong>Werdykt:</strong> ${esc(record.verdict.threat_label)}</p>
    <p><strong>Klienci:</strong> ${esc(record.observable.source_ips)} &middot; <strong>Zapytania DNS:</strong> ${esc(record.observable.query_count)}</p>
    <p><strong>Aktywne źródła danych:</strong><br>${sources}</p>
    ${audit.ai_status === 'ok' ? '' : '<p style="color:#ffd54f;">AI analysis unavailable - rule-based verdict only.</p>'}
    ${section('Analiza (PL)', record.verdict.analysis_pl)}
    ${section('Summary (EN)', record.verdict.summary_en)}
    ${section('Primary evidence', audit.primary_evidence)}
    ${section('Supporting context', audit.supporting_context)}
    <p style="margin:14px 0 4px;color:#888;font-size:12px;text-transform:uppercase;">Scoring trace</p>
    <ol style="font-size:12px;color:#bbb;line-height:1.5;padding-left:18px;">${record.rule.trace.map((t) => `<li>${esc(t)}</li>`).join('')}</ol>
  </div>
  <div style="text-align:center;font-size:11px;color:#777;padding:12px;">
    Raport wygenerowany przez system Cyber Sentinel &middot; analysis #${esc(record.analysis_result_id)} &middot; indicator #${esc(record.indicator_id)}
  </div>
</div></body></html>`;

return {
  json: {
    subject: `Cyber Sentinel ${theme.label} ${score}/5 | ${record.observable.fqdn} (${record.observable.observable_ip})`,
    html,
  },
};
